}
```

Hmm — cleaner: one mechanism. For a static source, the resolved schema object is stable (same reference every resolve), so the SAME WeakMap keyed by the resolved schema object gives both compile-once-at-register (pre-seed it at register) and per-call caching for dynamic sources. That's elegant:

```ts
register(definition, execute) {
  const resolved = this.resolveDefinition(definition);
  const validators: WeakMap<object, ValidateFunction> = new WeakMap();
  validators.set(resolved.inputSchema, compileSchema(resolved.name, resolved.inputSchema));
  this.tools.set(resolved.name, {definitionSource: definition, execute, validators});
}

private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
  let validate = tool.validators.get(definition.inputSchema);
  if (!validate) {
    validate = compileSchema(definition.name, definition.inputSchema);
    tool.validators.set(definition.inputSchema, definition.inputSchema ... wait
